const x=$json;
const required=["conversation_id","channel","channel_user_id","message_id"];
const missing=required.filter(k=>x[k]===undefined||x[k]===null||x[k]==="");
if(missing.length) return [{json:{...x,state_result:{status:"reject",reason:"missing_state_identity_fields",missing}}}];
return [{json:{...x,state_input:{valid:true}}}];

const x=$json;
/*
Replace this node in production with Supabase/Redis lookup.
Expected loaded state shape is:
{stage,intent,selected_product,selected_variant,cart_id,turn_count,
 language,script,register,escalation,updated_at}
*/
const loaded=x.persisted_state??null;
const defaultState={
 stage:"NEW",
 intent:null,
 selected_product:null,
 selected_variant:null,
 cart_id:null,
 turn_count:0,
 language:x.language??null,
 script:x.script??null,
 register:x.register??null,
 escalation:{required:false,status:null,reason:null},
 last_message_id:null
};
return [{json:{...x,state_before:loaded??defaultState,state_store_status:loaded?"loaded":"default_initialized"}}];

const x=$json;
const s={...(x.state_before??{})};
const turn=Number(s.turn_count??0)+1;
return [{json:{...x,state_working:{...s,turn_count:turn,last_message_id:x.message_id}}}];

const x=$json;
const s={...(x.state_working??{})};
if(x.intent?.name) s.intent=x.intent.name;
if(x.language) s.language=x.language;
if(x.script) s.script=x.script;
if(x.register) s.register=x.register;
if(x.selected_product!==undefined) s.selected_product=x.selected_product;
if(x.selected_variant!==undefined) s.selected_variant=x.selected_variant;
if(x.cart_id!==undefined) s.cart_id=x.cart_id;
if(x.escalation?.required!==undefined) s.escalation=x.escalation;
return [{json:{...x,state_working:s}}];

const x=$json,s={...(x.state_working??{})},intent=x.intent?.name;
const allowed={
 NEW:["BROWSING","DISCOVERY","WAITING_FOR_CUSTOMER","HUMAN_ESCALATION"],
 BROWSING:["DISCOVERY","PRODUCT_INTEREST","WAITING_FOR_CUSTOMER","HUMAN_ESCALATION"],
 DISCOVERY:["PRODUCT_INTEREST","CONSIDERING","WAITING_FOR_CUSTOMER","HUMAN_ESCALATION"],
 PRODUCT_INTEREST:["CONSIDERING","PRODUCT_SELECTED","WAITING_FOR_CUSTOMER","HUMAN_ESCALATION"],
 CONSIDERING:["PRODUCT_SELECTED","OBJECTION_HANDLING","WAITING_FOR_CUSTOMER","HUMAN_ESCALATION"],
 OBJECTION_HANDLING:["CONSIDERING","PRODUCT_SELECTED","WAITING_FOR_CUSTOMER","HUMAN_ESCALATION"],
 PRODUCT_SELECTED:["CART_BUILDING","CONSIDERING","WAITING_FOR_CUSTOMER","HUMAN_ESCALATION"],
 CART_BUILDING:["CHECKOUT_READY","PRODUCT_SELECTED","WAITING_FOR_CUSTOMER","HUMAN_ESCALATION"],
 CHECKOUT_READY:["PURCHASED","CART_BUILDING","HUMAN_ESCALATION"],
 PURCHASED:["POST_PURCHASE","HUMAN_ESCALATION"],
 POST_PURCHASE:["CLOSED","HUMAN_ESCALATION"],
 WAITING_FOR_CUSTOMER:["BROWSING","DISCOVERY","PRODUCT_INTEREST","CONSIDERING","PRODUCT_SELECTED","CART_BUILDING","CHECKOUT_READY","HUMAN_ESCALATION"],
 HUMAN_ESCALATION:["CLOSED"],
 CLOSED:[]
};
let target=s.stage;
if(intent==="product_discovery") target=s.stage==="NEW"?"DISCOVERY":"BROWSING";
if(intent==="product_question"||intent==="comparison"||intent==="pricing"||intent==="availability") target="CONSIDERING";
if(["cart_add","cart_update","cart_remove","cart_view"].includes(intent)) target="CART_BUILDING";
if(["checkout_start","checkout_confirm"].includes(intent)) target="CHECKOUT_READY";
if(intent==="human_request"||intent==="complaint"||intent==="payment_dispute"||intent==="safety") target="HUMAN_ESCALATION";
if(intent==="order_status"||intent==="return_exchange") target="POST_PURCHASE";
const current=s.stage??"NEW";
const permitted=(allowed[current]??[]).includes(target)||target===current;
const finalStage=permitted?target:current;
return [{json:{...x,state_transition:{from:current,requested:target,applied:finalStage,permitted}}}];

const x=$json;
return [{json:{...x,persistence:{
 conversation_id:x.conversation_id,
 channel:x.channel,
 channel_user_id:x.channel_user_id,
 state:x.state_after,
 updated_at:new Date().toISOString()
}}}];

const x=$json;
/*
Production: replace with Supabase upsert into `conversations`.
This starter does not pretend to persist data without your credentials.
*/
return [{json:{...x,state_persistence:{
 status:"ready_to_connect",
 operation:"upsert",
 table:"conversations",
 payload:x.persistence
}}}];
